      const topTex = top.map((f) => (f.t === 'add' && (top.length > 1 || c.n !== 1n || !inFraction) ? paren(f) : texOf(f)));
      const bottomTex = bottom.map((f) => (f.t === 'add' && (bottom.length > 1 || c.d !== 1n) ? paren(f) : texOf(f)));
