        asin: () => pow(sub(num(1), pow(u, 2)), num(new Frac(-1n, 2n))),
        acos: () => neg(pow(sub(num(1), pow(u, 2)), num(new Frac(-1n, 2n)))),
        atan: () => pow(add(num(1), pow(u, 2)), -1),
        sinh: () => fn('cosh', u),
        cosh: () => fn('sinh', u),
        tanh: () => sub(num(1), pow(fn('tanh', u), 2)),
